settings.customCss:
/* MegaForm Gen-3 split-photo shell. Scope: .mfp.mfp-verdant-member-registration */
.mfp.mfp-verdant-member-registration{
  --vd-bg:#0d1a12;
  --vd-card:var(--mf-page-surface,var(--mf-preset-surface,#f9f6f0));
  --vd-ink:var(--mf-page-text,var(--mf-preset-text,#1a2018));
  --vd-heading:var(--mf-page-heading,var(--mf-preset-text,#1a2018));
  --vd-muted:var(--mf-page-muted,color-mix(in srgb,var(--vd-ink) 58%,transparent));
  --vd-line:var(--mf-page-border,var(--mf-preset-border,#e2ddd4));
  --vd-input:var(--mf-page-input-bg,var(--mf-preset-surface,#ffffff));
  --vd-primary:var(--mf-page-primary,var(--mf-preset-primary,#3d7a4a));
  --vd-primary-hover:color-mix(in srgb,var(--vd-primary) 82%,#000000);
  --vd-soft:color-mix(in srgb,var(--vd-primary) 10%,var(--vd-card));
  --vd-on-primary:var(--mf-preset-on-primary,#ffffff);
  --vd-error:#c0392b;
  --vd-font:var(--mf-page-font-family,Inter,system-ui,-apple-system,"Segoe UI",Roboto,sans-serif);
  --vd-display:Georgia,"Times New Roman",serif;
  width:100%;
  max-width:1152px;
  margin:0 auto;
  color:var(--vd-ink);
  font-family:var(--vd-font);
}
.mfp.mfp-verdant-member-registration,.mfp.mfp-verdant-member-registration *,.mfp.mfp-verdant-member-registration *::before,.mfp.mfp-verdant-member-registration *::after{box-sizing:border-box}
.mfp-verdant-member-registration .mfp-stage{width:100%;padding:32px;border-radius:24px;background:var(--vd-bg)}
.mfp-verdant-member-registration .mfp-card{
  display:grid;
  grid-template-columns:minmax(280px,5fr) minmax(430px,7fr);
  width:min(100%,896px);
  min-height:650px;
  margin:0 auto;
  overflow:hidden;
  border:1px solid color-mix(in srgb,var(--vd-line) 62%,transparent);
  border-radius:24px;
  background:var(--vd-card);
  box-shadow:0 32px 80px rgba(0,0,0,.48);
}
.mfp-verdant-member-registration .mfp-hero{position:relative;min-height:100%;overflow:hidden;color:#ffffff}
.mfp-verdant-member-registration .mfp-hero-image{
  position:absolute;
  inset:0;
  background-image:url('/Modules/MegaForm/img/verdant-member-registration/hero.jpg');
  background-position:center;
  background-size:cover;
}
.DnnModule .mfp-verdant-member-registration .mfp-hero-image{background-image:url('/DesktopModules/MegaForm/Assets/img/verdant-member-registration/hero.jpg')}
.mfp-verdant-member-registration .mfp-hero-overlay{
  position:absolute;
  inset:0;
  background:linear-gradient(160deg,rgba(10,10,10,.68) 0%,rgba(10,10,10,.20) 54%,color-mix(in srgb,var(--vd-primary) 18%,transparent) 100%);
}
.mfp-verdant-member-registration .mfp-brand{position:absolute;z-index:2;top:32px;left:32px;display:flex;align-items:center;gap:10px}
.mfp-verdant-member-registration .mfp-brand-mark{
  display:grid;
  place-items:center;
  width:32px;
  height:32px;
  border-radius:8px;
  background:var(--vd-primary);
  color:#ffffff;
  font-size:14px;
  font-weight:800;
}
.mfp-verdant-member-registration .mfp-brand-name{color:#ffffff;font-size:13px;font-weight:800;letter-spacing:.16em}
.mfp-verdant-member-registration .mfp-hero-copy{position:absolute;z-index:2;right:0;bottom:0;left:0;padding:40px}
.mfp-verdant-member-registration .mfp-hero-title{
  max-width:13ch;
  margin:0;
  color:#ffffff;
  font-family:var(--vd-display);
  font-size:clamp(26px,3vw,34px);
  font-weight:700;
  line-height:1.22;
}
.mfp-verdant-member-registration .mfp-hero-sub{margin:14px 0 0;color:rgba(255,255,255,.72);font-size:14px;line-height:1.55}
.mfp-verdant-member-registration .mfp-hero-rule{width:40px;height:2px;margin-top:20px;border-radius:999px;background:var(--vd-primary)}
.mfp-verdant-member-registration .mfp-form-pane{display:flex;min-width:0;flex-direction:column;justify-content:center;padding:44px 48px;background:var(--vd-card)}
.mfp-verdant-member-registration .mfp-back-label{display:inline-flex;align-items:center;gap:7px;margin:0 0 28px;color:var(--vd-muted);font-size:12px;font-weight:600}
.mfp-verdant-member-registration .mfp-eyebrow{margin:0 0 7px;color:var(--vd-primary);font-size:10px;font-weight:800;letter-spacing:.34em;text-transform:uppercase}
.mfp-verdant-member-registration .mfp-form-title{margin:0;color:var(--vd-heading);font-family:var(--vd-display);font-size:clamp(32px,4vw,42px);font-weight:700;line-height:1.08}
.mfp-verdant-member-registration .mfp-form-subtitle{max-width:46ch;margin:10px 0 28px;color:var(--vd-muted);font-size:14px;line-height:1.6}
.mfp-verdant-member-registration .mfp-stack{display:grid;gap:16px}
.mfp-verdant-member-registration .mfp-field-row{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}
.mfp-verdant-member-registration .mf-field-group{min-width:0;margin:0}
.mfp-verdant-member-registration .mf-field-label{display:block;margin:0 0 7px;color:var(--vd-heading);font-size:12px;font-weight:800;letter-spacing:.035em;text-transform:uppercase}
.mfp-verdant-member-registration .mf-required{color:var(--vd-error)}
.mfp-verdant-member-registration .mf-input,.mfp-verdant-member-registration .mf-select,.mfp-verdant-member-registration .mf-textarea,
.mfp-verdant-member-registration input:not([type='checkbox']):not([type='radio']),.mfp-verdant-member-registration select,.mfp-verdant-member-registration textarea{
  width:100%!important;
  min-height:46px!important;
  padding:11px 15px!important;
  border:1px solid var(--vd-line)!important;
  border-radius:12px!important;
  outline:0!important;
  background:var(--vd-input)!important;
  color:var(--vd-ink)!important;
  box-shadow:none!important;
  font:inherit!important;
  font-size:14px!important;
  transition:border-color .16s ease,box-shadow .16s ease!important;
}
.mfp-verdant-member-registration .mf-textarea,.mfp-verdant-member-registration textarea{min-height:106px!important;resize:vertical!important}
.mfp-verdant-member-registration .mf-input:focus,.mfp-verdant-member-registration .mf-select:focus,.mfp-verdant-member-registration .mf-textarea:focus,
.mfp-verdant-member-registration input:focus,.mfp-verdant-member-registration select:focus,.mfp-verdant-member-registration textarea:focus{
  border-color:var(--vd-primary)!important;
  box-shadow:0 0 0 3px color-mix(in srgb,var(--vd-primary) 16%,transparent)!important;
}
.mfp-verdant-member-registration input::placeholder,.mfp-verdant-member-registration textarea::placeholder{color:color-mix(in srgb,var(--vd-muted) 56%,transparent)}
.mfp-verdant-member-registration .mf-field-help,.mfp-verdant-member-registration .mf-field-error{margin-top:5px;font-size:12px;line-height:1.4}
.mfp-verdant-member-registration .mf-field-error{color:var(--vd-error)}
.mfp-verdant-member-registration .mfp-chip-field .mf-option-group{display:flex!important;flex-wrap:wrap!important;gap:8px!important;grid-template-columns:none!important}
.mfp-verdant-member-registration .mfp-chip-field .mf-option-item{display:inline-flex!important;width:auto!important;margin:0!important;padding:0!important}
.mfp-verdant-member-registration .mfp-chip-field .mf-option-control{position:absolute!important;width:1px!important;height:1px!important;opacity:0!important;clip-path:inset(50%)!important}
.mfp-verdant-member-registration .mfp-chip-field .mf-option-ui{
  display:inline-flex!important;
  align-items:center!important;
  min-height:32px!important;
  padding:7px 13px!important;
  border:1px solid var(--vd-line)!important;
  border-radius:999px!important;
  background:var(--vd-input)!important;
  color:var(--vd-muted)!important;
  box-shadow:none!important;
  transition:all .16s ease!important;
}
.mfp-verdant-member-registration .mfp-chip-field .mf-option-label{color:inherit!important;font-size:12px!important;font-weight:600!important}
.mfp-verdant-member-registration .mfp-chip-field .mf-option-control:checked + .mf-option-ui{border-color:var(--vd-primary)!important;background:var(--vd-soft)!important;color:var(--vd-primary)!important}
.mfp-verdant-member-registration .mfp-chip-field .mf-option-control:focus-visible + .mf-option-ui{outline:2px solid var(--vd-primary)!important;outline-offset:2px!important}
.mfp-verdant-member-registration .mfp-check-field .mf-option-group{display:block!important}
.mfp-verdant-member-registration .mfp-check-field .mf-option-item{display:flex!important;align-items:flex-start!important;gap:10px!important;margin:0!important;padding:0!important}
.mfp-verdant-member-registration .mfp-check-field .mf-option-control{position:static!important;width:17px!important;height:17px!important;margin:3px 0 0!important;accent-color:var(--vd-primary)!important;opacity:1!important}
.mfp-verdant-member-registration .mfp-check-field .mf-option-ui{display:block!important;padding:0!important;border:0!important;background:transparent!important;color:var(--vd-muted)!important}
.mfp-verdant-member-registration .mfp-check-field .mf-option-label{color:inherit!important;font-size:14px!important;line-height:1.55!important}
.mfp-verdant-member-registration .mfp-actions{display:flex;align-items:center;gap:12px;margin-top:22px}
.mfp-verdant-member-registration .mfp-btn{
  display:inline-flex;
  min-height:48px;
  align-items:center;
  justify-content:center;
  gap:10px;
  border:1px solid transparent;
  border-radius:12px;
  padding:12px 22px;
  font:inherit;
  font-size:14px;
  font-weight:800;
  text-decoration:none;
  cursor:pointer;
  transition:transform .12s ease,background .16s ease,border-color .16s ease,opacity .16s ease;
}
.mfp-verdant-member-registration .mfp-btn:hover{transform:translateY(-1px)}
.mfp-verdant-member-registration .mfp-btn-primary{flex:1;background:var(--vd-ink);color:var(--vd-on-primary)}
.mfp-verdant-member-registration .mfp-btn-primary:hover{background:color-mix(in srgb,var(--vd-ink) 86%,var(--vd-primary))}
.mfp-verdant-member-registration .mfp-btn-secondary{border-color:var(--vd-line);background:transparent;color:var(--vd-muted)}
.mfp-verdant-member-registration .mfp-divider{display:flex;align-items:center;gap:12px;margin:18px 0;color:var(--vd-muted);font-size:12px}
.mfp-verdant-member-registration .mfp-divider::before,.mfp-verdant-member-registration .mfp-divider::after{content:"";height:1px;flex:1;background:var(--vd-line)}
.mfp-verdant-member-registration .mfp-provider-row{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}
.mfp-verdant-member-registration .mfp-provider{border-color:var(--vd-line);background:transparent;color:var(--vd-ink)}
.mfp-verdant-member-registration .mfp-provider:hover{border-color:var(--vd-primary);color:var(--vd-primary)}
.mfp-verdant-member-registration .mfp-footnote{margin:24px 0 0;text-align:center;color:var(--vd-muted);font-size:14px}
.mfp-verdant-member-registration .mfp-footnote a{color:var(--vd-primary);font-weight:800;text-decoration:none}
.mfp-verdant-member-registration .mfp-hidden-fields{display:none!important}
.mfp-verdant-member-registration .mf-form-title,.mfp-verdant-member-registration .mf-form-description,.mfp-verdant-member-registration .mf-success-message,.mfp-verdant-member-registration .mf-form-actions{display:none!important}
.mf-form-wrapper:has(.mfp-verdant-member-registration)>.mf-form-inner{width:100%!important;max-width:1152px!important}
.mf-form-wrapper:has(.mfp-verdant-member-registration) .mf-form-actions{display:none!important}
@media(max-width:760px){
  .mfp-verdant-member-registration .mfp-stage{padding:14px}
  .mfp-verdant-member-registration .mfp-card{grid-template-columns:1fr;min-height:0;border-radius:20px}
  .mfp-verdant-member-registration .mfp-hero{min-height:190px}
  .mfp-verdant-member-registration .mfp-brand{top:20px;left:20px}
  .mfp-verdant-member-registration .mfp-hero-copy{display:none}
  .mfp-verdant-member-registration .mfp-form-pane{padding:28px 24px 32px}
  .mfp-verdant-member-registration .mfp-back-label{margin-bottom:22px}
}
@media(max-width:520px){
  .mfp-verdant-member-registration .mfp-stage{padding:0;border-radius:20px}
  .mfp-verdant-member-registration .mfp-field-row,.mfp-verdant-member-registration .mfp-provider-row{grid-template-columns:1fr}
  .mfp-verdant-member-registration .mfp-form-pane{padding:26px 20px 30px}
  .mfp-verdant-member-registration .mfp-form-title{font-size:32px}
  .mfp-verdant-member-registration .mfp-actions{align-items:stretch;flex-direction:column-reverse}
  .mfp-verdant-member-registration .mfp-btn{width:100%}
}

.mfp-verdant-member-registration .mfp-progress-steps{display:flex;align-items:center;margin:0 0 28px;padding:0;list-style:none}
.mfp-verdant-member-registration .mfp-progress-step{position:relative;display:flex;flex:1;align-items:center}
.mfp-verdant-member-registration .mfp-progress-step:last-child{flex:0}
.mfp-verdant-member-registration .mfp-progress-step::after{content:"";height:2px;flex:1;margin:0 7px;background:var(--vd-line)}
.mfp-verdant-member-registration .mfp-progress-step:last-child::after{display:none}
.mfp-verdant-member-registration .mfp-progress-step span{display:grid;width:28px;height:28px;place-items:center;border-radius:999px;background:var(--vd-line);color:var(--vd-muted);font-size:12px;font-weight:800}
.mfp-verdant-member-registration .mfp-progress-step.is-active span,.mfp-verdant-member-registration .mfp-progress-step.is-done span{background:var(--vd-primary);color:var(--vd-on-primary)}
.mfp-verdant-member-registration .mfp-progress-step.is-done::after{background:var(--vd-primary)}
.mfp-verdant-member-registration .mfp-page{display:none!important}
.mfp-verdant-member-registration .mfp-page.is-active{display:block!important}
.mfp-verdant-member-registration .mfp-page-head{margin-bottom:24px}
.mfp-verdant-member-registration .mfp-page-head .mfp-form-subtitle{margin-bottom:0}
.mfp-verdant-member-registration .mfp-review-card{padding:24px;border:1px solid var(--vd-line);border-radius:16px;background:var(--vd-soft)}
.mfp-verdant-member-registration .mfp-review-card h3{margin:0;color:var(--vd-heading);font-family:var(--vd-display);font-size:24px}
.mfp-verdant-member-registration .mfp-review-card p{margin:8px 0 0;color:var(--vd-muted);font-size:14px;line-height:1.6}
